    private async Task HandleSubmit()
    {
        isLoading = true;

        try
        {
            var result = await PaymentService.CreateAsync(model);

            isSuccess = result?.success ?? false;
            message = result?.message ?? "No response received";

            if (isSuccess)
            {
                await ShowMessage(result!.message ?? "Payment deleted successfully.","alert-success");
                await Task.Delay(1500);
             
                Nav.NavigateTo("/payment/list");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message);
        }
        finally
        {
            isLoading = false;
        }
    }
    private async Task ShowMessage(string text, string cssClass)
    {
        messageText = text;
        messageClass = cssClass;
        showMessage = true;

        StateHasChanged();
        await Task.Delay(1000);
        showMessage = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Cancel()
    {
        Nav.NavigateTo("/payment/list");
    }

